--!strict
local Players=game:GetService("Players");local ReplicatedStorage=game:GetService("ReplicatedStorage");local player=Players.LocalPlayer;local folder=ReplicatedStorage:WaitForChild("Remotes",10);if not folder then return end;local update=folder:WaitForChild("QueueUpdated")::RemoteEvent;local leave=folder:WaitForChild("LeaveQueue")::RemoteEvent
local gui=Instance.new("ScreenGui");gui.Name="QueueGui";gui.ResetOnSpawn=false;gui.Parent=player.PlayerGui;local frame=Instance.new("Frame");frame.Position=UDim2.fromScale(.72,.68);frame.Size=UDim2.fromScale(.25,.25);frame.BackgroundColor3=Color3.fromRGB(25,32,48);frame.BackgroundTransparency=.12;frame.Visible=false;frame.Parent=gui;local text=Instance.new("TextLabel");text.Size=UDim2.fromScale(1,.7);text.BackgroundTransparency=1;text.TextColor3=Color3.new(1,1,1);text.TextScaled=true;text.TextWrapped=true;text.Parent=frame;local button=Instance.new("TextButton");button.Position=UDim2.fromScale(.15,.74);button.Size=UDim2.fromScale(.7,.2);button.Text="取消排隊";button.TextScaled=true;button.Parent=frame;button.Activated:Connect(function()leave:FireServer();frame.Visible=false end)
local modeState=folder:WaitForChild("ModeStateChanged")::RemoteEvent;modeState.OnClientEvent:Connect(function(d)if d.inMatch or d.inTower then frame.Visible=false end end)
update.OnClientEvent:Connect(function(d) local mine=table.find(d.players,player.DisplayName)~=nil;if mine then frame.Visible=true;text.Text=string.format("%s  %d/%d\n%s\n%s",d.mode,d.count,d.max,d.remaining and ("開始倒數："..d.remaining) or "等待開始",table.concat(d.players,", ")) end end)
